// generated by lia multi-emit → rust
#![allow(non_snake_case, unused_assignments, unused_variables, unused_parens, unused_mut, dead_code)]
fn _lia_val(x: impl ToString) -> String { x.to_string() }

pub fn match_number(mut n: i64) -> String {
    match n {
        0 => {
            return _lia_val(100);
        }
        1 => {
            return _lia_val(200);
        }
        _ => {
            return _lia_val(999);
        }
    }
}

pub fn unwrap_option(opt: Option<i64>, default_val: i64) -> i64 {
    match opt {
        Some(v) => {
            return v;
        }
        None => {
            return default_val;
        }
        _ => {
            return default_val;
        }
    }
}

fn main() {
    assert_eq!(match_number(0), "100");
    assert_eq!(match_number(1), "200");
    assert_eq!(match_number(42), "999");
    assert_eq!(unwrap_option(Some(77), 0), 77);
    assert_eq!(unwrap_option(None, 404), 404);
    println!("M003_A_RUST_RUNTIME_PASS");
}
